DetectorFactory.seed = 42   # reproducibilidad langdetect

# ================== CONFIGURACIÓN ADAPTADA ================== 
PROJECT_ID = os.getenv("GCP_PROJECT") or "fincas-para-boda"
INPUT_DIR = os.getenv("INPUT_DIR") or "." # Busca en la carpeta actual
MAX_WORKERS = int(os.getenv("MAX_WORKERS") or "8")
BATCH_COMMIT_EVERY = 1
MAX_DOC_FIELD_CHARS = 50000
CHUNK_MAX_CHARS = 80000
CHUNK_OVERLAP = 600
NEAR_DUP_BANDS = 4
NEAR_DUP_BAND_BITS = 16
NEAR_DUP_MAX_HAMMING = 5

COLL_PROVIDERS = "proveedores"
COLL_INDEX = "índice_de_ingestión"

SELECTORES = {
    "nombre": ["h1.nombre-proveedor", "h1.título", "h1", "header h1"],
    "ubicación": [".ubicación-proveedor", ".ubicación", ".dirección", ".dirección-proveedor"],
    "calificación": [".calificación .valor", ".valor-calificación", "[itemprop='valorCalificación']", ".calificación"],
    "rango_precios": [".rango-precios", ".precios", ".precios-proveedor"],
    "promociones": [".promociones", ".promo", ".ofertas", ".ofertas-especiales"],
    "elementos_premios": [".premios li", ".insignias-premio .premio", ".premios .elemento"],
    "categories_items": [".categories a", ".tags a", ".breadcrumbs a", ".taxonomy a"],
    "description_container": [
        ".vendor-description", ".description", "article", "#content", ".content", ".main"
    ],
}

REDACCIÓN = {
    "strip_elements": ["script", "style", "meta", "noscript", "iframe", "link", "form"],
    "strip_classes_like": ["ad", "ads", "advert", "sponsored", "cookie", "newsletter", "tracking", "share", "social"],
    "remove_attrs_prefixes": ["on", "data-"],
    "blank_href_src": True,
    "remove_emails": True,
    "remove_urls": True,
    "remove_phones": True,
    "remove_credit_cards": True,
    "remove_iban": True,
    "remove_user_handles": True,
    "remove_ip_addresses": True,
    "disallowed_patterns": [
        r"https?://[^\s)\"'>]+",
        r"\bwww\.[^\s)\"'>]+",
    ],
}

# ================== UTILIDADES ================== 
def sha256(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8", "ignore")).hexdigest()

def stable_hash64(s: str) -> int:
    h = hashlib.blake2b(s.encode("utf-8", "ignore"), digest_size=8).digest()
    return int.from_bytes(h, "big", signed=False)

def simhash(s: str, nbits: int = 64) -> int:
    tokens = re.findall(r"[A-Za-zÀ-ÿ0-9_]+", s.lower())
    weights = {}
    for t in tokens:
        weights[t] = weights.get(t, 0) + 1
    v = [0] * nbits
    for t, w in weights.items():
        h = stable_hash64(t)
        for i in range(nbits):
            bit = (h >> i) & 1
            v[i] += w if bit == 1 else -w
    output = 0
    for i in range(nbits):
        if v[i] >= 0:
            output |= (1 << i)
    return output

def hamming_distance(a: int, b: int) -> int:
    return (a ^ b).bit_count()

def band_keys(simh: int, bands: int = NEAR_DUP_BANDS, band_bits: int = NEAR_DUP_BAND_BITS) -> List[str]:
    keys = []
    for i in range(bands):
        v = (simh >> (i * band_bits)) & ((1 << band_bits) - 1)
        keys.append(f"{i}:{v:0{band_bits//4}x}")
    return keys

def textify(el) -> str:
    if not el:
        return ""
    return re.sub(r"\s+\n", "\n", " ".join(el.stripped_strings)).strip()

def find_first_text(soup: BeautifulSoup, selectors: List[str]) -> str:
    for sel in selectors:
        el = soup.select_one(sel)
        if el:
            t = textify(el)
            if t:
                return t
    return ""

def find_all_texts(soup: BeautifulSoup, selectors: List[str]) -> List[str]:
    items = []
    for sel in selectors:
        for el in soup.select(sel):
            t = textify(el)
            if t:
                items.append(t)
    seen = set()
    out = []
    for t in items:
        if t not in seen:
            seen.add(t)
            out.append(t)
    return out

def remove_attrs_recursively(soup: BeautifulSoup, prefixes: List[str]):
    for tag in soup.find_all(True):
        for attr in list(tag.attrs.keys()):
            low = attr.lower()
            if any(low.startswith(pref) for pref in prefixes):
                del tag.attrs[attr]

def sanitize_html(html: str, cfg=REDACTION) -> BeautifulSoup:
    soup = BeautifulSoup(html, "lxml")
    for c in soup.find_all(string=lambda text: isinstance(text, Comment)):
        c.extract()
    for name in cfg["strip_elements"]:
        for tag in soup.find_all(name):
            tag.decompose()
    if cfg["strip_classes_like"]:
        class_regex = re.compile("|".join([re.escape(c) for c in cfg["strip_classes_like"]]), re.I)
        for tag in soup.find_all(True, class_=class_regex):
            tag.decompose()
    if cfg["remove_attrs_prefixes"]:
        remove_attrs_recursively(soup, cfg["remove_attrs_prefixes"])
    if cfg.get("blank_href_src", True):
        for a in soup.find_all("a"):
            for k in ("href", "rel"):
                if k in a.attrs:
                    del a.attrs[k]
        for im in soup.find_all("img"):
            for k in ("src", "srcset", "data-src"):
                if k in im.attrs:
                    del im.attrs[k]
    txt = soup.get_text(" ", strip=True)
    if cfg.get("remove_emails"):
        txt = re.sub(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", "", txt)
    if cfg.get("remove_urls"):
        txt = re.sub(r"https?://[^\s)\"'>]+", "", txt)
        txt = re.sub(r"\bwww\.[^\s)\"'>]+", "", txt)
    if cfg.get("remove_phones"):
        txt = re.sub(r"(\+?\d[\d\-\s().]{7,}\d)", "", txt)
    if cfg.get("remove_credit_cards"):
        txt = re.sub(r"\b(?:\d[ -]*?){13,19}\b", "", txt)
    if cfg.get("remove_iban"):
        txt = re.sub(r"\b[A-Z]{2}\d{2}[A-Z0-9]{11,30}\b", "", txt)
    if cfg.get("remove_user_handles"):
        txt = re.sub(r"(?!\w)@\w{2,40}", "", txt)
        txt = re.sub(r"\b(t\.me|twitter\.com|x\.com|instagram\.com|fb\.com|facebook\.com)/[A-Za-z0-9_.-]+\b", "", txt, flags=re.I)
    if cfg.get("remove_ip_addresses"):
        txt = re.sub(r"\b(?:\d{1,3}\.){3}\d{1,3}\b", "", txt)
    for pat in cfg.get("disallowed_patterns", []):
        txt = re.sub(pat, "", txt, flags=re.I)
    body = soup.body or soup
    body.clear()
    body.append(txt)
    return soup

def html_to_markdown(soup: BeautifulSoup, container_selectors: List[str]) -> Tuple[str, str]:
    container = None
    for sel in container_selectors:
        container = soup.select_one(sel)
        if container and container.get_text(strip=True):
            break
    if not container:
        container = soup.body or soup
    clean_html = str(container)
    md_text = md(
        clean_html,
        heading_style="ATX",
        strip=[],
        convert=['table', 'ol', 'ul', 'em', 'strong', 'a', 'blockquote', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6']
    ).strip()
    md_text = re.sub(r"\n{3,}", "\n\n", md_text).strip()
    content_hash = sha256(md_text)
    return md_text, content_hash

def estimate_tokens(s: str) -> int:
    return max(1, len(s) // 4)

def chunk_by_headings(md_text: str, max_chars: int, overlap: int) -> List[str]:
    paras = md_text.split("\n")
    chunks = []
    buf = []
    size = 0
    for line in paras:
        is_heading = bool(re.match(r"^#{1,6}\s", line))
        if is_heading and size >= max_chars * 0.75:
            chunk = "\n".join(buf).strip()
            if chunk:
                chunks.append(chunk)
            if overlap > 0 and chunk:
                tail = chunk[-overlap:]
                buf = [tail]
                size = len(tail)
            else:
                buf = []
                size = 0
        buf.append(line)
        size += len(line) + 1
        if size >= max_chars:
            chunk = "\n".join(buf).strip()
            if chunk:
                chunks.append(chunk)
            if overlap > 0 and chunk:
                tail = chunk[-overlap:]
                buf = [tail]
                size = len(tail)
            else:
                buf = []
                size = 0
    if buf:
        chunk = "\n".join(buf).strip()
        if chunk:
            chunks.append(chunk)
    if not chunks:
        if len(md_text) <= max_chars:
            return [md_text]
        out = []
        start = 0
        while start < len(md_text):
            end = min(len(md_text), start + max_chars)
            out.append(md_text[start:end])
            start = end - overlap if overlap > 0 else end
        return out
    return chunks

def parse_rating(value: str) -> Optional[float]:
    try:
        m = re.search(r"(\d+[.,]?\d*)", value)
        if m:
            return float(m.group(1).replace(",", "."))
    except:
        pass
    return None

def extract_key_values(soup: BeautifulSoup) -> Dict[str, str]:
    kv = {}
    for dl in soup.find_all("dl"):
        dts = dl.find_all("dt")
        dds = dl.find_all("dd")
        for dt_el, dd_el in zip(dts, dds):
            key = textify(dt_el)
            val = textify(dd_el)
            if key and val:
                kv[key] = val
    for li in soup.find_all("li"):
        t = textify(li)
        if ":" in t:
            k, v = t.split(":", 1)
            k = k.strip()
            v = v.strip()
            if len(k) <= 60 and k and v:
                kv.setdefault(k, v)
    return kv

def extract_tables(soup: BeautifulSoup, limit_cells: int = 2000) -> List[Dict]:
    tables = []
    for idx, table in enumerate(soup.find_all("table"), start=1):
        rows = []
        headers = []
        thead = table.find("thead")
        if thead:
            theads = [textify(th) for th in thead.find_all(["th", "td"])]
            headers = [h for h in theads if h]
        for tr in table.find_all("tr"):
            cells = [textify(td) for td in tr.find_all(["td", "th"])]
            if cells:
                rows.append(cells)
        flat_cells = sum(len(r) for r in rows)
        if flat_cells == 0:
            continue
        if flat_cells > limit_cells:
            rows = rows[:max(1, limit_cells // max(1, len(rows[0])))]
        cap_el = table.find("caption")
        caption = textify(cap_el) if cap_el else ""
        tables.append({
            "seq": idx,
            "caption": caption,
            "headers": headers,
            "rows": rows
        })
    return tables

def detect_language(text: str) -> Optional[str]:
    try:
        if not text or len(text) < 40:
            return None
        return lang_detect(text)
    except:
        return None

def extract_fields(soup: BeautifulSoup) -> Dict:
    name = find_first_text(soup, SELECTORES["nombre"])
    location = find_first_text(soup, SELECTORES["ubicación"])
    rating_str = find_first_text(soup, SELECTORES["calificación"])
    rating = parse_rating(rating_str) if rating_str else None
    price_range = find_first_text(soup, SELECTORES["rango_precios"]) or None
    promotions = find_first_text(soup, SELECTORES["promociones"]) or None
    awards = find_all_texts(soup, SELECTORES["elementos_premios"])
    categories = [c.lower() for c in find_all_texts(soup, SELECTORES["categories_items"])]
    kv = extract_key_values(soup)
    tables = extract_tables(soup)
    return {
        "name": name,
        "location": location,
        "rating": rating,
        "price_range": price_range,
        "promotions": promotions,
        "awards": awards,
        "categories": sorted(set(categories)),
        "attributes": kv,
        "tables": tables,
    }

def compliance_scan(text: str, extra_disallow: List[str]) -> List[str]:
    violations = []
    base_patterns = [
        r"https?://",
        r"\bwww\.",
        r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}",
    ]
    patterns = base_patterns + extra_disallow
    for p in patterns:
        if re.search(p, text, flags=re.I):
            violations.append(p)
    return sorted(set(violations))

# ================== FIRESTORE ================== 
def get_client(project_id: Optional[str] = None):
    return firestore.Client(project=project_id or PROJECT_ID)

def ensure_unique_provider_id(db, base_id: str, content_hash: str) -> str:
    doc_ref = db.collection(COLL_PROVIDERS).document(base_id)
    if doc_ref.get().exists:
        return f"{base_id}-{content_hash[:6]}"
    return base_id

@dataclass
class WriteUnit:
    provider_id: str
    provider_doc: Dict
    chunks: List[str]
    tables: List[Dict]
    content_hash: str
    source_filename: str

def write_provider(db, unit: WriteUnit):
    batch = db.batch()
    prov_ref = db.collection(COLL_PROVIDERS).document(unit.provider_id)
    now = dt.datetime.utcnow()

    base_doc = {
        **unit.provider_doc,
        "content_hash": unit.content_hash,
        "source_filename": Path(unit.source_filename).name,
        "updated_at": now,
        "num_chunks": len(unit.chunks),
        "num_tables": len(unit.tables),
    }
    batch.set(prov_ref, base_doc, merge=True)

    chunks_coll = prov_ref.collection("chunks")
    for i, text in enumerate(unit.chunks, start=1):
        doc_id = f"{i:04d}"
        batch.set(
            chunks_coll.document(doc_id),
            {
                "seq": i,
                "text": text,
                "token_estimate": estimate_tokens(text),
                "content_hash": unit.content_hash,
            },
            merge=False,
        )

    if unit.tables:
        tables_coll = prov_ref.collection("tables")
        for t in unit.tables:
            doc_id = f"{t['seq']:04d}"
            batch.set(
                tables_coll.document(doc_id),
                {
                    "seq": t["seq"],
                    "caption": t["caption"],
                    "headers": t["headers"],
                    "rows": t["rows"],
                    "content_hash": unit.content_hash,
                },
                merge=False,
            )

    idx_ref = db.collection(COLL_INDEX).document(unit.content_hash)
    batch.set(
        idx_ref,
        {"provider_id": unit.provider_id, "source_filename": base_doc["source_filename"], "created_at": now},
        merge=False,
    )

    batch.commit()

# ================== PIPELINE ================== 
@dataclass
class Policy:
    disallow_patterns: List[str] = field(default_factory=list)
    strict: bool = True

@dataclass
class ParseResult:
    ok: bool
    reason: Optional[str]
    write_unit: Optional[WriteUnit]
    content_hash: Optional[str]
    simhash64: Optional[int]
    near_dup_of: Optional[str]
    language: Optional[str]

class NearDupIndex:
    def __init__(self, bands=NEAR_DUP_BANDS, band_bits=NEAR_DUP_BAND_BITS):
        self.bands = bands
        self.band_bits = band_bits
        self.bucket = {}

    def add(self, simh: int, provider_id: str):
        for key in band_keys(simh, self.bands, self.band_bits):
            self.bucket.setdefault(key, []).append((simh, provider_id))

    def query(self, simh: int, max_hamming=NEAR_DUP_MAX_HAMMING) -> Optional[str]:
        for key in band_keys(simh, self.bands, self.band_bits):
            for s2, pid in self.bucket.get(key, []):
                if hamming_distance(simh, s2) <= max_hamming:
                    return pid
        return None

def process_html_file(path: Path, policy: Policy) -> ParseResult:
    try:
        html = path.read_text(encoding="utf-8", errors="ignore")
    except Exception as e:
        return ParseResult(False, f"read_error: {e}", None, None, None, None, None)

    soup = sanitize_html(html, REDACTION)
    fields = extract_fields(soup)
    md_text, content_hash = html_to_markdown(soup, SELECTORES["description_container"])

    violations = compliance_scan(md_text, policy.disallow_patterns)
    if policy.strict and violations:
        return ParseResult(False, f"policy_violations: {violations}", None, content_hash, None, None, None)

    lang = detect_language(md_text)

    base_name = fields["name"] or path.stem
    base_id = slugify(base_name) or slugify(path.stem)
    description_md_head = md_text[:MAX_DOC_FIELD_CHARS]
    chunks = chunk_by_headings(md_text, CHUNK_MAX_CHARS, CHUNK_OVERLAP)

    provider_doc = {
        "name": fields["name"],
        "location": fields["location"],
        "rating": fields["rating"],
        "price_range": fields["price_range"],
        "promotions": fields["promotions"],
        "awards": fields["awards"],
        "categories": fields["categories"],
        "attributes": fields["attributes"],
        "description_md": description_md_head,
        "language": lang,
        "tags": [],
        "simhash64": None,
    }

    s64 = simhash(md_text)
    provider_doc["simhash64"] = f"{s64:016x}"

    write_unit = WriteUnit(
        provider_id=base_id,
        provider_doc=provider_doc,
        chunks=chunks,
        tables=fields["tables"],
        content_hash=content_hash,
        source_filename=str(path),
    )
    return ParseResult(True, None, write_unit, content_hash, s64, None, lang)

def main():
    import argparse
    parser = argparse.ArgumentParser(description="Ingesta avanzada HTML -> Firestore (sin imágenes)")
    parser.add_argument("--input-dir", default=INPUT_DIR, help="Carpeta con archivos .html")
    parser.add_argument("--project", default=PROJECT_ID, help="ID de proyecto de GCP")
    parser.add_argument("--max-workers", type=int, default=MAX_WORKERS, help="Hilos para parseo")
    parser.add_argument("--strict-policy", action="store_true", default=True, help="Bloquear si hay violaciones")
    parser.add_argument("--policy-file", default="", help="JSON con array 'disallow_patterns'")
    parser.add_argument("--skip-remote-dedupe", action="store_true", help="No consultar Firestore por hash (solo dedupe local)")
    parser.add_argument("--limit", type=int, default=0, help="Limitar número de archivos (debug)")
    args = parser.parse_args()

    extra_patterns = []
    if args.policy_file:
        try:
            j = json.loads(Path(args.policy_file).read_text(encoding="utf-8"))
            extra_patterns = j.get("disallow_patterns", [])
        except Exception as e:
            print(f"[WARN] No pude leer policy-file: {e}")
    policy = Policy(disallow_patterns=extra_patterns, strict=args.strict_policy)

    in_dir = Path(args.input_dir)
    if not in_dir.exists():
        print(f"[ERR] No existe la carpeta {in_dir}")
        sys.exit(1)

    html_files = [p for p in in_dir.rglob("*") if p.suffix.lower() in (".html", ".htm")]
    html_files.sort()
    if args.limit and args.limit > 0:
        html_files = html_files[:args.limit]

    print(f"Encontrados {len(html_files)} archivos HTML en {in_dir}")

    db = get_client(args.project)

    concurrent_results: List[ParseResult] = []
    with ThreadPoolExecutor(max_workers=args.max_workers) as ex:
        futures = {ex.submit(process_html_file, p, policy): p for p in html_files}
        for fut in tqdm(as_completed(futures), total=len(futures), desc="Parseando"):
            res = fut.result()
            concurrent_results.append(res)

    seen_hashes = set()
    ndx = NearDupIndex()
    ok_units: List[WriteUnit] = []
    policy_skips = 0
    read_errs = 0
    near_dup_skips = 0

    for res in concurrent_results:
        if not res.ok:
            if res.reason and "policy_violations" in res.reason:
                policy_skips += 1
            else:
                read_errs += 1
            continue
        if res.content_hash in seen_hashes:
            continue
        if res.simhash64 is not None:
            similar_to = ndx.query(res.simhash64)
            if similar_to:
                near_dup_skips += 1
                continue

        unit = res.write_unit
        assert unit is not None
        unit.provider_id = ensure_unique_provider_id(db, unit.provider_id, unit.content_hash)
        ok_units.append(unit)
        seen_hashes.add(unit.content_hash)
        if res.simhash64 is not None:
            ndx.add(res.simhash64, unit.provider_id)

    if not args.skip_remote_dedupe:
        retained_units = []
        for u in tqdm(ok_units, desc="Filtrando duplicados remotos"):
            idx_ref = db.collection(COLL_INDEX).document(u.content_hash)
            if idx_ref.get().exists:
                continue
            retained_units.append(u)
        ok_units = retained_units

    print(f"Listos para escribir {len(ok_units)} providers | policy skips: {policy_skips} | near-dup skips: {near_dup_skips} | errores lectura: {read_errs}")

    written = 0
    for u in tqdm(ok_units, desc="Escribiendo en Firestore"):
        write_provider(db, u)
        written += 1

    print(f"Escritura finalizada. Escritos: {written}, saltados por política: {policy_skips}, casi-duplicados: {near_dup_skips}, errores: {read_errs}")

if __name__ == "__main__":
    main()
